function getWindowMinutesUsed() {
  try { const cfg = $('[WIN-IN] Touch Last Inbound').first().json; if (cfg && cfg.window_minutes) return Number(cfg.window_minutes); } catch(e) {}
  try { const cfg = $('[WIN-FU] Evaluate Followup Window').first().json; if (cfg && cfg.window_minutes) return Number(cfg.window_minutes); } catch(e) {}
  return 1440;
}

const item = $input.first().json;
function toTitleCase(s) { return String(s||'').toLowerCase().replace(/\b\w/g, c => c.toUpperCase()); }
const nombre = toTitleCase(item.nombre_cliente||'estimado/a cliente');
const modelo = toTitleCase(item.modelo||'su vehiculo');
const marca = (item.marca||'KIA').toUpperCase();

if (marca !== 'KIA' && marca !== 'HYUNDAI') {
  throw new Error(`[GUARD CONTACTO_2] marca inválida: "${marca}" conv=${item.conversation_id}`);
}

function normalizeWaPhone(raw) {
  return String(raw || '').replace(/\D/g, '');
}
const telefonoWa = normalizeWaPhone(item.phone_e164 || item.telefono);

const CONTACTO_2_TEMPLATES = {
  KIA: [
    { name: 'kia_contacto2_v1', lang: 'es', params: [{ type: 'text', text: nombre }, { type: 'text', text: modelo }] },
    { name: 'kia_contacto2_v2', lang: 'es', params: [{ type: 'text', text: nombre }] },
  ],
  HYUNDAI: [
    { name: 'hyundai_contacto2_v1', lang: 'es', params: [{ type: 'text', text: nombre }, { type: 'text', text: modelo }] },
    { name: 'hyundai_contacto2_v2', lang: 'es', params: [{ type: 'text', text: nombre }] },
  ],
};
let opciones = CONTACTO_2_TEMPLATES[marca];
const lastTplAt = item.last_template_sent_at ? new Date(item.last_template_sent_at) : null;
const repeatedRecent = item.last_template_sent && lastTplAt && (Date.now() - lastTplAt.getTime()) < 24 * 60 * 60 * 1000;
if (repeatedRecent) opciones = opciones.filter(o => o.name !== item.last_template_sent);
if (!opciones.length) throw new Error(`[GUARD TEMPLATE] template repetido en 24h: ${item.last_template_sent}`);
const tpl = opciones[Math.floor(Math.random() * opciones.length)];

const template_payload = {
  messaging_product: 'whatsapp',
  to: telefonoWa,
  type: 'template',
  template: {
    name: tpl.name,
    language: { code: tpl.lang },
    components: [{ type: 'body', parameters: tpl.params }],
  },
};

return [{json:{...item, template_payload, template_name_used: tpl.name, telefono_wa: telefonoWa,
  next_estado:'CONTACTED_2', next_intentos:(parseInt(item.intentos_realizados)||0)+1,
  next_followup_tipo:'CONTACTED_3', window_minutes_used: getWindowMinutesUsed()
}}];

function getWindowMinutesUsed() {
  try { const cfg = $('[WIN-IN] Touch Last Inbound').first().json; if (cfg && cfg.window_minutes) return Number(cfg.window_minutes); } catch(e) {}
  try { const cfg = $('[WIN-FU] Evaluate Followup Window').first().json; if (cfg && cfg.window_minutes) return Number(cfg.window_minutes); } catch(e) {}
  return 1440;
}

