={{ "SET search_path TO sales_prod, public, extensions;\n" + ((() => {
  const src = $('Code — Mensaje CONTACTO_3').first().json;
  const err = $json.error
    ? String($json.error.message || $json.error.description || JSON.stringify($json.error)).replace(/'/g, "''")
    : '';
  const phoneRaw = src.phone_e164 || (src.telefono ? ('+' + String(src.telefono).replace(/^\+/, '')) : '');
  const phone = String(phoneRaw || '').replace(/'/g, "''");
  const templateName = String(src.template_name_used || '').replace(/'/g, "''");
  if (err) {
    return `SET search_path TO sales_prod, public, extensions;\nSELECT * FROM fail_claimed_followup('${src.followup_id}'::uuid, '${err}'::text);`;
  }
  return `SET search_path TO sales_prod, public, extensions;\nSELECT * FROM complete_claimed_followup_success('${src.followup_id}'::uuid, '${phone}'::text, '${templateName}'::text);`;
})()) }}

